import { ChevronDown } from 'lucide-react';
import { type RefObject, useRef, useState } from 'react';

import { Button } from '@/components/ui/Button';
import type { CatalogSubcategoryFilterOption } from './components/CatalogFilters/types/catalog-filters';

import { useStickyPanel } from './logic/use-sticky-panel';

import { CatalogFilters } from './components/CatalogFilters';
import type { CatalogPriceFilterValue } from './components/CatalogFilters/types/catalog-filters';
import { CatalogSorting } from './components/CatalogSorting';
import type { CatalogSortRule } from './components/CatalogSorting/types/catalog-sorting';

type CatalogControlsProps = {
  products: { price: number }[];
  priceFilter: CatalogPriceFilterValue;
  selectedCategoryIds: string[];
  sortRules: CatalogSortRule[];
  showFilters?: boolean;
  showSorting?: boolean;
  subcategoryOptions?: CatalogSubcategoryFilterOption[];
  containerRef?: RefObject<HTMLDivElement | null>;
  onPriceFilterChange: (value: CatalogPriceFilterValue) => void;
  onSelectedCategoryIdsChange: (categoryIds: string[]) => void;
  onSortRulesChange: (rules: CatalogSortRule[]) => void;
};

export function CatalogControls({
  products,
  priceFilter,
  selectedCategoryIds,
  sortRules,
  showFilters = true,
  showSorting = true,
  subcategoryOptions,
  containerRef,
  onPriceFilterChange,
  onSelectedCategoryIdsChange,
  onSortRulesChange,
}: CatalogControlsProps) {
  const [isOpen, setIsOpen] = useState(false);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  useStickyPanel({ sentinelRef, panelRef, containerRef });

  if (!showFilters && !showSorting) {
    return null;
  }

  return (
    <div ref={sentinelRef} className="lg:self-start">
      <aside ref={panelRef} className="rounded-xl bg-background/60 backdrop-blur-xl">
        <div className="lg:hidden">
          <Button
            type="button"
            variant="ghost"
            className="flex h-auto w-full justify-between px-4 py-3"
            onClick={() => setIsOpen((currentValue) => !currentValue)}
          >
            Фильтры и сортировка

            <ChevronDown
              className={`size-4 transition-transform ${isOpen ? 'rotate-180' : ''}`}
            />
          </Button>
        </div>

        <div
          className={`space-y-6 rounded-2xl bg-white p-4 shadow-card-xl lg:mt-0 lg:block lg:pt-4 ${isOpen ? 'mt-3' : 'hidden'}`}
        >
          {showSorting && (
            <CatalogSorting value={sortRules} onChange={onSortRulesChange} />
          )}

          {showFilters && (
            <CatalogFilters
              products={products}
              priceFilter={priceFilter}
              selectedCategoryIds={selectedCategoryIds}
              subcategoryOptions={subcategoryOptions}
              onPriceFilterChange={onPriceFilterChange}
              onSelectedCategoryIdsChange={onSelectedCategoryIdsChange}
            />
          )}
        </div>
      </aside>
    </div>
  );
}
import { type RefObject, useEffect, useRef } from 'react';

import { HEADER_ANIMATION_DURATION_MS, HEADER_ANIMATION_EASING, getHeaderHeight, useHeaderStore } from '@/shared/header';

type UseStickyPanelOptions = {
  sentinelRef: RefObject<HTMLDivElement | null>;
  panelRef: RefObject<HTMLDivElement | null>;
  containerRef?: RefObject<HTMLDivElement | null>;
};

export function useStickyPanel({
  sentinelRef,
  panelRef,
  containerRef,
}: UseStickyPanelOptions) {
  const isHeaderHidden = useHeaderStore((s) => s.isHidden);
  const isHeaderHiddenRef = useRef(isHeaderHidden);
  isHeaderHiddenRef.current = isHeaderHidden;

  useEffect(() => {
    const sentinel = sentinelRef.current;
    const panel = panelRef.current;
    const container = containerRef?.current ?? null;
    if (!sentinel || !panel) return;

    panel.style.transition = `top ${HEADER_ANIMATION_DURATION_MS}ms ${HEADER_ANIMATION_EASING}`;

    const reset = () => {
      panel.style.position = '';
      panel.style.top = '';
      panel.style.left = '';
      panel.style.width = '';
      sentinel.style.minHeight = '';
    };

    const update = () => {
      if (window.innerWidth < 1024) {
        reset();
        return;
      }

      const headerHeight = getHeaderHeight();
      const gap = 16;
      const effectiveHeaderHeight = isHeaderHiddenRef.current ? 0 : headerHeight;
      const stickyTop = effectiveHeaderHeight + gap;

      const panelHeight = panel.offsetHeight;
      sentinel.style.minHeight = `${panelHeight}px`;

      const sentinelRect = sentinel.getBoundingClientRect();

      if (sentinelRect.top > stickyTop) {
        reset();
        return;
      }

      const containerBottom = container
        ? container.getBoundingClientRect().bottom
        : sentinelRect.bottom;
      const maxTop = containerBottom - panelHeight;
      const top = Math.min(stickyTop, maxTop);

      panel.style.position = 'fixed';
      panel.style.top = `${top}px`;
      panel.style.left = `${sentinelRect.left}px`;
      panel.style.width = `${sentinel.offsetWidth}px`;
    };

    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    update();
    return () => {
      window.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
    };
  }, [sentinelRef, panelRef, containerRef]);
}

