  size = 'default',
  asChild = false,
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot.Root : 'button';

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={buttonVariants({
        variant,
        size,
        className,
      })}
      {...props}
    />
  );
}

