  variant = 'secondary',
  showAddToCartButton = true,
  showBuyNowButton = true,
  showFavouriteButton = false,
  showSellerContactsButton = false,
  selectedAdditions = [],
  isProductConfigurationValid = true,
  onInvalidProductConfiguration,
}: ItemActionsProps) {
  const navigate = useNavigate();
  const addItem = useCartStore((state) => state.addItem);

  function handleBuyNow() {
    if (itemType === 'product') {
      if (!isProductConfigurationValid) {
        onInvalidProductConfiguration?.();
        return;
      }
      addItem(item, selectedAdditions);
      navigate('/checkout');
    }
  }

  const isProduct = itemType === 'product';

  if (
    !showAddToCartButton &&
    !showBuyNowButton &&
    !showFavouriteButton &&
    !(itemType === 'ad' && showSellerContactsButton)
  ) {
    return null;
  }

  return (
    <div className="flex flex-col gap-2">
      {!isProduct && showSellerContactsButton && (
        <SellerContactsButton ad={item} variant={variant} />
      )}

      {(showAddToCartButton || showFavouriteButton) && (
        <div className="flex items-start gap-2">
          {showAddToCartButton && (
            <div className="flex-1">
              {itemType === 'product' ? (
                <AddToCartButton
                  itemType="product"
                  item={item as Product}
                  variant={variant}
                  selectedAdditions={selectedAdditions}
                  isConfigurationValid={isProductConfigurationValid}
                  onInvalidConfiguration={onInvalidProductConfiguration}
                />
              ) : (
                <AddToCartButton
                  itemType="ad"
                  item={item as Ad}
                  variant={variant}
                />
              )}
            </div>
          )}

          {showFavouriteButton && (
            <FavouriteButton
              item={
                itemType === 'product'
                  ? { productId: item.id }
                  : { adId: item.id }
              }
              className={[
                'shrink-0 rounded-lg',
                variant === 'details' ? 'size-9' : 'size-8',
              ].filter(Boolean).join(' ')}
            />
          )}
        </div>
      )}



      {isProduct && showBuyNowButton && (
        <Button
          type="button"
          variant='accent'
          size={variant === 'details' ? 'lg' : 'default'}
          className={['w-full', getProductActionHeightClass(variant)].filter(Boolean).join(' ')}
          onClick={handleBuyNow}
        >
          Купить в 1 клик
        </Button>
      )}
    </div>
  );
}
import { Button } from '@/components/ui/Button';
import type { Ad } from '@/entities/ad';
import { useCartStore } from '@/entities/cart';
import type { Product, SelectedProductAddition } from '@/entities/product';
import { createCartConfigurationKey } from '@/entities/product/lib/product-additions';
import {
  ProductQuantityCounter,
  getProductActionHeightClass,
  type ProductQuantityCounterVariant,
} from '@/widgets/ProductQuantityCounter';

type AddToCartButtonProps = {
  variant?: ProductQuantityCounterVariant;
  selectedAdditions?: SelectedProductAddition[];
  isConfigurationValid?: boolean;
  onInvalidConfiguration?: () => void;
} & (
    | { itemType: 'product'; item: Product }
    | { itemType: 'ad'; item: Ad }
  );

export function AddToCartButton({
  variant = 'secondary',
  itemType,
  item,
  selectedAdditions = [],
  isConfigurationValid = true,
  onInvalidConfiguration,
}: AddToCartButtonProps) {
  const configurationKey =
    itemType === 'product'
      ? createCartConfigurationKey(item.id, selectedAdditions)
      : item.id;
  const quantity = useCartStore((state) =>
    state.items.find((cartItem) =>
      (cartItem.configurationKey ?? cartItem.product.id) === configurationKey,
    )?.quantity ?? 0,
  );
  const addItem = useCartStore((state) => state.addItem);
  const adItems = useCartStore((state) => state.adItems);
  const addAdItem = useCartStore((state) => state.addAdItem);
  const removeAdItem = useCartStore((state) => state.removeAdItem);

  if (itemType === 'ad') {
    const isInCart = adItems.some((i) => i.ad.id === item.id);

    return (
      <Button
        type="button"
        variant={isInCart ? 'secondary' : 'accent'}
        size={variant === 'details' ? 'lg' : 'default'}
        className={['w-full', getProductActionHeightClass(variant)].filter(Boolean).join(' ')}
        onClick={() => (isInCart ? removeAdItem(item.id) : addAdItem(item))}
      >
        {isInCart ? 'Убрать из корзины' : 'В корзину'}
      </Button>
    );
  }

  if (quantity > 0) {
    return (
      <ProductQuantityCounter
        productId={configurationKey}
        variant={variant}
      />
    );
  }

  return (
    <Button
      type="button"
      variant="accent"
      size={variant === 'details' ? 'lg' : 'default'}
      className={['w-full', getProductActionHeightClass(variant)].filter(Boolean).join(' ')}
      onClick={() => {
        if (!isConfigurationValid) {
          onInvalidConfiguration?.();
          return;
        }
        addItem(item, selectedAdditions);
      }}
    >
      В корзину
    </Button>
  );
}
import { useState } from 'react';

import { Button } from '@/components/ui/Button';
import type { Ad } from '@/entities/ad';
import { LinkifyText } from '@/shared/utils/linkify';
import { Modal } from '@/components/ui/Modal';
import {
  getProductActionHeightClass,
  type ProductQuantityCounterVariant,
} from '@/widgets/ProductQuantityCounter';

type SellerContactsButtonProps = {
  ad: Ad;
  variant?: ProductQuantityCounterVariant;
};

const contactBadgeClass =
  'rounded-md bg-muted/60 px-3 py-1.5 text-sm font-medium text-foreground';

function getContactValues(ad: Ad): string[] {
  return [
    ad.contactPhone,
    ad.contactTelegram,
    ad.contactEmail,
    ad.contactOther,
  ].filter((value): value is string => Boolean(value));
}

export function SellerContactsButton({
  ad,
  variant = 'card',
}: SellerContactsButtonProps) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const sellerName = ad.seller?.nickname ?? 'Продавец';
  const contactValues = getContactValues(ad);

  return (
    <>
      <Button
        type="button"
        variant="secondary"
        size={variant === 'details' ? 'lg' : 'default'}
        className={['w-full', getProductActionHeightClass(variant)].filter(Boolean).join(' ')}
        onClick={() => setIsModalOpen(true)}
      >
        Контакты
      </Button>

      <Modal
        isOpen={isModalOpen}
        title={`${sellerName}`}
        size="sm"
        bodyClassName="overflow-y-auto p-5"
        onClose={() => setIsModalOpen(false)}
      >
        {contactValues.length > 0 ? (
          <div className="flex flex-col gap-2">
            {contactValues.map((value, index) => (
              <div key={`${value}-${index}`} className={contactBadgeClass}>
                <LinkifyText text={value} />
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-muted-foreground">
            Продавец пока не указал контакты.
          </p>
        )}
      </Modal>
    </>
  );
}
import { Minus, Plus } from 'lucide-react';

import { useCartStore } from '@/entities/cart';

export type ProductQuantityCounterVariant = 'card' | 'details';

type ProductQuantityCounterProps = {
  productId: string;
  variant?: ProductQuantityCounterVariant;
};

export function getProductActionHeightClass(
  variant: ProductQuantityCounterVariant,
) {
  return variant === 'details' ? 'h-9' : 'h-8';
}

export function ProductQuantityCounter({
  productId,
  variant = 'card',
}: ProductQuantityCounterProps) {
  const quantity = useCartStore((state) => state.getItemQuantity(productId));
  const increaseItem = useCartStore((state) => state.increaseItem);
  const decreaseItem = useCartStore((state) => state.decreaseItem);

  return (
    <div
      className={[
        'grid grid-cols-[2.25rem_1fr_2.25rem] overflow-hidden rounded-lg border border-border bg-background',
        getProductActionHeightClass(variant),
      ].filter(Boolean).join(' ')}
    >
      <button
        type="button"
        className="flex h-full cursor-pointer items-center justify-center hover:bg-muted"
        onClick={() => decreaseItem(productId)}
      >
        <Minus className="size-4" />
      </button>

      <div className="flex items-center justify-center text-sm font-medium">
        {quantity}
      </div>

      <button
        type="button"
        className="flex h-full cursor-pointer items-center justify-center hover:bg-muted"
        onClick={() => increaseItem(productId)}
      >
        <Plus className="size-4" />
      </button>
    </div>
  );
}
