import type {
  ComponentProps,
  ComponentType,
  ReactNode,
} from 'react';
import { Link } from 'react-router-dom';

import { Button } from '@/components/ui/Button';

type StateCardIcon = ComponentType<{
  className?: string;
  strokeWidth?: number;
}>;

type StateCardAction =
  | {
    label: ReactNode;
    to: string;
    onClick?: never;
    variant?: ComponentProps<typeof Button>['variant'];
  }
  | {
    label: ReactNode;
    onClick: () => void;
    to?: never;
    variant?: ComponentProps<typeof Button>['variant'];
  };

type StateCardProps = {
  icon?: StateCardIcon;
  title: ReactNode;
  description: ReactNode;
  action?: StateCardAction;
  className?: string;
};

export function StateCard({
  icon: Icon,
  title,
  description,
  action,
  className,
}: StateCardProps) {
  return (
    <section
      className={[
        'mx-auto max-w-xl rounded-3xl p-6 text-center shadow-card-2xl bg-white sm:px-8 sm:py-10',
        className,
      ].filter(Boolean).join(' ')}
    >
      <div className="flex flex-col gap-6">
        {Icon && (
          <span className="mx-auto flex items-center justify-center">
            <Icon className="size-8" strokeWidth={1.5} />
          </span>
        )}

        <div className="flex flex-col gap-3">
          <h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">
            {title}
          </h1>

          <p className="text-sm leading-6 text-muted-foreground">
            {description}
          </p>
        </div>

        {action && (
          <div className="flex justify-center">
            {action.to ? (
              <Button asChild variant={action.variant}>
                <Link to={action.to}>{action.label}</Link>
              </Button>
            ) : (
              <Button
                type="button"
                variant={action.variant}
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            )}
          </div>
        )}
      </div>
    </section>
  );
}
