  3	type UsePageScrollLazyLoadingProps<T> = {
  4	  fetchFunction: () => Promise<T[]>;
  5	  initialChunkSize?: number;
  6	  chunkSize?: number;
  7	  enabled?: boolean;
  8	  threshold?: number;
  9	};
 10	
 11	export function usePageScrollLazyLoading<T>({
 12	  fetchFunction,
 13	  initialChunkSize = 12,
 14	  chunkSize = 12,
 15	  enabled = true,
 16	  threshold = 0.9,
 17	}: UsePageScrollLazyLoadingProps<T>) {
 18	  const [items, setItems] = useState<T[]>([]);
 19	  const [isLoading, setIsLoading] = useState(false);
 20	  const [hasMore, setHasMore] = useState(true);
 21	  const [error, setError] = useState<string | null>(null);
 22	
 23	  const allItemsRef = useRef<T[]>([]);
 24	  const offsetRef = useRef(0);
 25	  const isInitializedRef = useRef(false);
 26	  const loadingRef = useRef(false);
 27	  const chunkSizeRef = useRef(chunkSize);
 28	
 29	  chunkSizeRef.current = chunkSize;
 30	
 31	  const loadInitialItems = async () => {
 32	    if (!enabled || isInitializedRef.current || loadingRef.current) return;
 33	
 34	    setIsLoading(true);
 35	    setError(null);
 36	    loadingRef.current = true;
 37	
 38	    try {
 39	      const allData = await fetchFunction();
 40	      allItemsRef.current = allData;
 41	
 42	      const initialItems = allData.slice(0, initialChunkSize);
 43	      setItems(initialItems);
 44	      offsetRef.current = initialChunkSize;
 45	      setHasMore(allData.length > initialChunkSize);
 46	      isInitializedRef.current = true;
 47	    } catch (err) {
 48	      setError(err instanceof Error ? err.message : 'Failed to load items');
 49	    } finally {
 50	      setIsLoading(false);
 51	      loadingRef.current = false;
 52	    }
 53	  };
 54	
 55	  const loadMoreItems = () => {
 56	    if (!enabled || !hasMore || !isInitializedRef.current || loadingRef.current) return;
 57	
 58	    loadingRef.current = true;
 59	    setIsLoading(true);
 60	
 61	    const start = offsetRef.current;
 62	    const end = start + chunkSizeRef.current;
 63	    const newItems = allItemsRef.current.slice(start, end);
 64	
 65	    setItems((prev) => [...prev, ...newItems]);
 66	    offsetRef.current = end;
 67	    setHasMore(end < allItemsRef.current.length);
 68	
 69	    setIsLoading(false);
 70	    loadingRef.current = false;
 71	  };
 72	
 73	  useEffect(() => {
 74	    const handleScroll = () => {
 75	      if (!hasMore || loadingRef.current) return;
 76	
 77	      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
 78	      const scrollHeight = document.documentElement.scrollHeight;
 79	      const clientHeight = window.innerHeight;
 80	
 81	      if ((scrollTop + clientHeight) / scrollHeight > threshold) {
 82	        loadMoreItems();
 83	      }
 84	    };
 85	
 86	    window.addEventListener('scroll', handleScroll, { passive: true });
 87	
 88	    return () => window.removeEventListener('scroll', handleScroll);
 89	  }, [hasMore, threshold]);
 90	
 91	  useEffect(() => {
 92	    if (enabled) {
 93	      loadInitialItems();
 94	    }
 95	  }, [enabled]);
 96	
 97	  return {
 98	    items,
 99	    isLoading,
100	    hasMore,
101	    error,
102	    loadMoreItems,
103	    refetch: loadInitialItems,
104	  };
105	}
