import { Link } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';

import type { BreadcrumbItem } from '../../types/breadcrumbs';

type BreadcrumbsListProps = {
  items: BreadcrumbItem[];
};

export function BreadcrumbsList({ items }: BreadcrumbsListProps) {
  return (
    <nav className="mx-auto flex max-w-7xl flex-wrap items-center gap-1 px-4 pt-8 text-sm text-muted-foreground">
      {items.map((item, index) => {
        const isLastItem = index === items.length - 1;

        return (
          <div
            key={`${item.id}-${item.href}`}
            className="flex items-center gap-1"
          >
            {index > 0 && <ChevronRight className="size-4" />}

            {isLastItem ? (
              <span className="text-foreground">{item.label}</span>
            ) : (
              <Link to={item.href} className="hover:text-foreground">
                {item.label}
              </Link>
            )}
          </div>
        );
      })}
    </nav>
  );
}import { useQuery } from '@tanstack/react-query';
import { useMatches, useSearchParams } from 'react-router-dom';

import { getAd } from '@/entities/ad';
import { getCatalogCategories } from '@/shared/catalog';
import { getProduct } from '@/entities/product/api/get-product';
import { getPlatformSectionIdFromPathname } from '@/shared/platform';

import { BreadcrumbsList } from './components/BreadcrumbsList';
import { buildBreadcrumbItems } from './logic/build-breadcrumb-items';
import { getCurrentAdSlug } from './logic/get-current-ad-slug';
import { getCurrentCategorySlug } from './logic/get-current-category-slug';
import { getCurrentProductSlug } from './logic/get-current-product-slug';
import type {
  BreadcrumbItem,
  BreadcrumbMatch,
} from './types/breadcrumbs';

type BreadcrumbsProps = {
  root?: BreadcrumbItem;
};

const defaultRoot: BreadcrumbItem = {
  id: 'home',
  href: '/',
  label: 'Главная',
};

function getActiveBreadcrumbSection(matches: BreadcrumbMatch[]) {
  const lastMatch = matches.at(-1);

  return getPlatformSectionIdFromPathname(lastMatch?.pathname ?? '/');
}

export function Breadcrumbs({ root = defaultRoot }: BreadcrumbsProps) {
  const matches = useMatches() as BreadcrumbMatch[];
  const [searchParams] = useSearchParams();

  const activeSection = getActiveBreadcrumbSection(matches);
  const categorySlug = getCurrentCategorySlug(matches);
  const productSlug = getCurrentProductSlug(matches);
  const adSlug = getCurrentAdSlug(matches);

  const { data: categories } = useQuery({
    queryKey: ['categories', activeSection],
    queryFn: () => getCatalogCategories({ section: activeSection }),
    enabled: Boolean(activeSection && (categorySlug || productSlug || adSlug)),
  });

  const { data: product } = useQuery({
    queryKey: ['product', productSlug],
    queryFn: () => getProduct(productSlug ?? ''),
    enabled: Boolean(productSlug),
  });

  const { data: ad } = useQuery({
    queryKey: ['ad', adSlug],
    queryFn: () => getAd(adSlug ?? ''),
    enabled: Boolean(adSlug),
  });

  const breadcrumbItems = buildBreadcrumbItems({
    matches,
    root,
    activeSection,
    categories,
    categorySlug,
    product,
    productSlug,
    ad,
    adSlug,
    searchQuery: searchParams.get('q')?.trim() ?? '',
  });

  if (breadcrumbItems.length <= 1) {
    return null;
  }

  return <BreadcrumbsList items={breadcrumbItems} />;
}
import type { CSSProperties } from 'react';
import { Outlet, ScrollRestoration } from 'react-router-dom';

import { headerHeightVar } from '@/shared/header';
import { mobileNavigationHeightVar } from '@/shared/main-navigation';

import { Breadcrumbs } from '@/widgets/Breadcrumbs';
import { Footer } from '@/widgets/Footer/Footer';
import { Header } from '@/widgets/Header/Header';
import { MainNavigation } from '@/widgets/MainNavigation/MainNavigation';
import { CookieNotice } from '@/widgets/CookieNotice';

export function MainLayout() {
  return (
    <div
      className="min-h-screen overflow-x-hidden bg-background pb-[var(--main-layout-mobile-bottom-padding)] text-foreground md:pb-0"
      style={
        {
          '--main-layout-mobile-bottom-padding': mobileNavigationHeightVar(),
        } as CSSProperties
      }
    >
      <Header />

      <div
        className="page-dot-background bg-page"
        style={{
          marginTop: headerHeightVar(),
          minHeight: `calc(100vh - ${headerHeightVar()})`,
        }}
      >
        <Breadcrumbs />

        <main className="mx-auto max-w-7xl px-4 py-8 pb-24">
          <Outlet />
        </main>
      </div>

      <Footer />

      <MainNavigation placement="mobileBottom" />

      <CookieNotice />

      <div
        id="app-modal-root"
        className="pointer-events-none fixed inset-0 z-[80]"
      />

      <div
        id="app-notification-root"
        className="pointer-events-none fixed inset-x-0 top-0 z-[90] h-0"
      />

      <ScrollRestoration />
    </div>
  );
}
export const BREADCRUMB_TYPE = {
  HOME: 'home',
  CATALOG: 'catalog',
  CATEGORY: 'category',
  PRODUCT: 'product',
  AD: 'ad',
  STATIC: 'static',
  SEARCH: 'search',
} as const;

export type BreadcrumbType =
  (typeof BREADCRUMB_TYPE)[keyof typeof BREADCRUMB_TYPE];

export type BreadcrumbDescriptor =
  | {
    type: typeof BREADCRUMB_TYPE.HOME;
    label: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.CATALOG;
    label: string;
    href?: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.CATEGORY;
    fallbackLabel?: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.PRODUCT;
    fallbackLabel?: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.AD;
    fallbackLabel?: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.STATIC;
    label: string;
    href?: string;
  }
  | {
    type: typeof BREADCRUMB_TYPE.SEARCH;
    fallbackLabel: string;
  };

export type BreadcrumbHandle = {
  breadcrumb?: BreadcrumbDescriptor;
};

export type BreadcrumbMatch = {
  id: string;
  pathname: string;
  params: Record<string, string | undefined>;
  handle?: BreadcrumbHandle;
};

export type BreadcrumbItem = {
  id: string;
  href: string;
  label: string;
};

